export const chatCommand = defineCommand({
    name: "chat",
    aliases: [
        {
            name: "resume",
            now: "chat --session <sessionId> (or chat --resume)",
            // `resume <id>` reattached that session; `resume` alone, the latest.
            argv: (rest, flags) => positionalAsFlag(rest, flags, "--session") ?? ["--resume", ...rest],
        },
    ],
    group: "develop",
    summary: "Chat with a running agent in an interactive REPL.",
    description: `
Follow-ups keep the session and continuation token. --message sends the first
turn, then stays open on a TTY. --session reattaches and replays the
transcript. --resume reattaches the most recently updated session. --json
sends one turn.`,
    flags: {
        ...chatFlags,
        resume: {
            type: "boolean",
            description: "Reattach the most recently updated session. Ignored with --session.",
        },
    },
    effect: "interactive",
    async run({ values }) {
        return cmdChat({
            dir: values.dir,
            messages: values.message,
            url: values.url,
            prod: values.prod,
            slug: values.slug,
            sessionId: sessionId(values),
            resume: values.resume,
            continuationToken: values["continuation-token"],
            bearerToken: values["bearer-token"],
            json: values.json,
            text: values.text,
            noColor: values["no-color"],
        });
    },
});
export const toolCallCommand = defineCommand({
    name: "tool call",
    aliases: ["call"],
    group: "develop",
    parentSummary: "Call an authored server tool with no model turn.",
    summary: "Call an authored server tool with no model turn (POST /v1/tools/:tool).",
    description: "Validates the input against the tool schema and prints the tool result. --json prints the full { ok, result, … } response. --session runs the tool inside that session and records it on the session's event stream.",
    args: [{ name: "tool", description: "Tool name.", required: true }],
    flags: {
        ...dirFlag,
        input: {
            type: "string",
            value: "<json>",
            description: "JSON object of tool arguments (default {}).",
        },
        ...sessionFlags,
        ...urlFlag,
        ...bearerTokenFlag,
        ...slugFlag,
        ...stateRootFlag,
        ...jsonFlag,
        ...prodRejectedFlag,
        ...dryRunFlag,
    },
    effect: "write",
    examples: [`agent-sdk tool call get_weather --input '{"city":"NYC"}' --json`],
    async run({ values, positionals }) {
        if (values["dry-run"] === true && values.url === undefined && values.prod !== true) {
            let input;
            try {
                input = JSON.parse(values.input ?? "{}");
            }
            catch {
                throw new CliUsageError("--input must be a JSON object");
            }
            localDryRun(`/v1/tools/${encodeURIComponent(positionals[0] ?? "")}`, {
                input,
                sessionId: sessionId(values),
            });
        }
        return cmdCall({
            dir: values.dir,
            toolName: positionals[0],
            toolInput: values.input,
            sessionId: sessionId(values),
            json: values.json,
            url: values.url,
            prod: values.prod,
            slug: values.slug,
            bearerToken: values["bearer-token"],
            stateRoot: values["state-root"],
        });
    },
});
